def norm_text(s:str)->str:
    s=s.replace('ي','ی').replace('ك','ک').replace('\u200f','').replace('\u200e','')
    for a,b in REPL: s=s.replace(a,b)
    s=re.sub(r'[ \t]+',' ',s); s=re.sub(r' *\n *','\n',s); s=re.sub(r'\s+([،؛؟.!])',r'\1',s); s=re.sub(r'([،؛؟.!])(?=[^\s\n])',r'\1 ',s)
    return s.strip()

def title_from(text:str,fallback:str)->str:
    first=text.splitlines()[0].strip() if text.splitlines() else fallback
    return first if first.startswith('#') else fallback

def review_khane(src:Path,out:Path,n:int):
    text=src.read_text(encoding='utf-8'); title=title_from(text,f'# خانه تو | قسمت {n}'); blocks=BLOCK_RE.findall(text)
    if not blocks: raise RuntimeError(f'no blocks {src}')
    reviewed=[]
    for ts,sp,body in blocks:
        sp=KHANE_MAP[n].get(sp,sp); body=norm_text(body)
        for a,b in KHANE_PHRASE.get(n,[]): body=body.replace(a,b)
        if len(body.strip())<=3 and n==1 and ts=='00:00:08 → 00:00:08': body='[نامفهوم]'
        reviewed.append((ts,sp,body))
    write_outputs(title,reviewed,out,n)
    assert [x[0] for x in blocks]==[x[0] for x in BLOCK_RE.findall((out/'timestamped'/f'{n}.md').read_text(encoding='utf-8'))]
    return len(blocks)

