def write_outputs(title,reviewed,out,n):
    out_ts=out/'timestamped'/f'{n}.md'; out_md=out/'md'/f'{n}.md'; out_txt=out/'txt'/f'{n}.txt'
    for p in (out_ts,out_md,out_txt): p.parent.mkdir(parents=True,exist_ok=True)
    out_ts.write_text(title+'\n\n'+''.join(f'[{ts}] **{sp}**\n\n{body}\n\n' for ts,sp,body in reviewed).rstrip()+'\n',encoding='utf-8')
    out_md.write_text(title+'\n\n'+''.join(f'**{sp}**\n\n{body}\n\n' for _,sp,body in reviewed).rstrip()+'\n',encoding='utf-8')
    out_txt.write_text(''.join(f'{sp}:\n{body}\n\n' for _,sp,body in reviewed).rstrip()+'\n',encoding='utf-8')

def review_dar_file(src:Path,out:Path,n:int):
    text=src.read_text(encoding='utf-8'); title=title_from(text,f'# در جستجوی خوشبختی | قسمت {n}'); blocks=BLOCK_RE.findall(text)
    if not blocks:
        pat=re.compile(r'(?ms)^\[(\d\d:\d\d:\d\d → \d\d:\d\d:\d\d)\]\s*\n\n(.*?)(?=^\[\d\d:\d\d:\d\d → |\Z)')
        blocks=[(ts,'دکتر کمیل رودی',body) for ts,body in pat.findall(text)]
    reviewed=[]
    for ts,sp,body in blocks:
        if sp.startswith('گوینده') or sp in {'media','گوینده نامشخص'}: sp='دکتر کمیل رودی'
        body=norm_text(body)
        for a,b in DAR_EXTRA: body=body.replace(a,b)
        reviewed.append((ts,sp,body))
    write_outputs(title,reviewed,out,n); return len(reviewed)

